class Solution:
    def minDiffInBST(self, root: TreeNode) -> int:
        stack = []
        node = root
        prev = None
        ans = 10**18
        while stack or node:
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            if prev is not None:
                ans = min(ans, node.val - prev)
            prev = node.val
            node = node.right
        return int(ans)

