import java.io.*;
import java.util.*;

class TreeNode {
    int val; TreeNode left, right;
    TreeNode(int v){ val=v; }
}

class Solution {
    public int minDiffInBST(TreeNode root) {
        Deque<TreeNode> st = new ArrayDeque<>();
        TreeNode node = root;
        int prev = 0, ans = Integer.MAX_VALUE;
        boolean hasPrev = false;
        while(!st.isEmpty() || node != null){
            while(node != null){ st.push(node); node=node.left; }
            node=st.pop();
            if(hasPrev) ans=Math.min(ans,node.val-prev);
            prev=node.val; hasPrev=true;
            node=node.right;
        }
        return ans;
    }
}

public class Main {
