        return s.isEmpty()?new String[0]:s.split(",");
    }
    static TreeNode buildTree(String line){
        String[] t=splitRoot(line);
        if(t.length==0 || t[0].trim().equals("null")) return null;
        TreeNode root=new TreeNode(Integer.parseInt(t[0].trim()));
